/** Bentuk mentah produk di "database". Direlasikan lewat slug kategori & merek. */
export interface ProductRecord {
  id: number
  slug: string
  name: string
  category_slug: string
  brand_slug: string | null
  tagline: { id: string; en: string }
  excerpt: { id: string; en: string }
  description: { id: string; en: string }
  badge: { id: string; en: string } | null
  packaging: string
  packaging_options: string[]
  specs: { label: { id: string; en: string }; value: string }[]
  benefits: { id: string; en: string }[]
  usage: { id: string; en: string }[]
  /** Jumlah foto di `public/gambar/produk/<slug>/`, agar galeri tidak meminta berkas yang tidak ada. */
  image_count: number
  placeholder: string
  is_featured: boolean
  is_bestseller: boolean
  sort_order: number
  updated_at: string
}

