/** Membangun objek gambar: `utama.jpg`, lalu bernomor urut. Di luar jumlah foto, `url` null. */
export function buildProductImage(record: ProductRecord, index = 0): ProductImage {
  const tersedia = index < record.image_count
  const berkas = index === 0 ? 'utama' : String(index + 1)

  return {
    id: record.id * 100 + index,
    url: tersedia ? `/gambar/produk/${record.slug}/${berkas}.jpg` : null,
    alt: {
      id: `Kemasan ${record.name}, ${record.tagline.id}`,
      en: `${record.name} packaging, ${record.tagline.en}`,
    },
    placeholder: record.placeholder,
  }
}
